"use strict";
// meta-modal: the project's introspection window. Its first page is the
// code-graph tab, which renders the file-level dependency graph produced by
// scripts/graph/scan.js (ui/web/graph-data.json). Read-only view: the data
// file is regenerated by rerunning the scanner, never by the UI.
//
// Layout tree: see docs/ui/ui.md meta-modal.
//   meta-modal
//   ├─ meta-sidebar      → meta-codegraph-btn (page switcher)
//   ├─ meta-viewport     → meta-codegraph-tab
//   │    ├─ meta-codegraph-opbar  (search / fit / reload / status)
//   │    └─ meta-codegraph-view   (cytoscape canvas + legend)
//   └─ meta-panel        → meta-codegraph-detail (selected node edges) + close-meta-btn

(function () {
  var App = (window.App = window.App || {});

  var DATA_URL = "graph-data.json";
  var LAYER_COLORS = {
    entry: "#1e3a8a",
    core: "#2563eb",
    "ui-electron": "#7c3aed",
    "ui-web": "#0d9488",
    tools: "#ea580c",
    providers: "#db2777",
    scripts: "#6b7280",
    other: "#9ca3af",
  };
  var INCOMING = "#2563eb";
  var OUTGOING = "#16a34a";
  var FOCUS_ZOOM = 0.8;
  var LABEL_ZOOM = 0.45;

  var overlay = null;
  var canvasEl = null;
  var statusEl = null;
  var searchEl = null;
  var detailEl = null;
  var archBadge = null;
  var archPanelEl = null;
  var cy = null;
  var data = null;
  var selectedId = null;

  // ---- Shell ----
  function el(tag, attrs, children) {
    var e = document.createElement(tag);
    attrs = attrs || {};
    for (var k in attrs) {
      if (!Object.prototype.hasOwnProperty.call(attrs, k)) continue;
      var v = attrs[k];
      if (v == null) continue;
      if (k === "className") e.className = v;
      else if (k === "dataset") { for (var d in v) e.setAttribute("data-" + d, v[d]); }
      else if (k === "html") e.innerHTML = v;
      else if (k === "onclick") e.addEventListener("click", v);
      else if (k === "oninput") e.addEventListener("input", v);
      else if (k === "value") e.value = v;
      else e.setAttribute(k, v);
    }
    if (children != null) {
      if (!Array.isArray(children)) children = [children];
      children.forEach(function (c) {
        if (c == null) return;
        e.appendChild(typeof c === "string" || typeof c === "number" ? document.createTextNode(String(c)) : c);
      });
    }
    return e;
  }

  function buildShell() {
    statusEl = el("span", { className: "meta-status", dataset: { name: "meta-status" } });
    searchEl = el("input", {
      className: "meta-graph-search",
      dataset: { name: "meta-graph-search" },
      type: "search",
      placeholder: "搜索文件路径（如 loops/nodes）",
      oninput: onSearch,
    });
    archBadge = el("button", {
      className: "meta-arch-badge",
      dataset: { name: "meta-arch-badge" },
      onclick: toggleArchPanel,
    }, "架构规则");
    var opbar = el("div", { className: "meta-codegraph-opbar", dataset: { name: "meta-codegraph-opbar" } }, [
      searchEl,
      el("button", { dataset: { name: "meta-graph-fit-btn" }, onclick: fitGraph }, "适应窗口"),
      el("button", { dataset: { name: "meta-graph-reload-btn" }, onclick: function () { loadGraph(true); } }, "重新加载"),
      archBadge,
      statusEl,
    ]);

    canvasEl = el("div", { className: "meta-codegraph-canvas", dataset: { name: "meta-codegraph-canvas" } });
    var legend = el("div", { className: "meta-codegraph-legend", dataset: { name: "meta-codegraph-legend" }, html:
      '<span class="meta-dot dot-core"></span>core' +
      '<span class="meta-dot dot-tools"></span>tools' +
      '<span class="meta-dot dot-ui"></span>ui' +
      '<span class="meta-dot dot-dyn"></span>虚线=运行时规则' +
      '<span class="meta-dot dot-in"></span>入边（谁依赖我）' +
      '<span class="meta-dot dot-out"></span>出边（我依赖谁）'
    });
    archPanelEl = el("div", { className: "meta-arch-panel", dataset: { name: "meta-arch-panel" } });
    archPanelEl.hidden = true;
    var view = el("div", { className: "meta-codegraph-view", dataset: { name: "meta-codegraph-view" } }, [canvasEl, legend, archPanelEl]);
    var tab = el("div", { className: "meta-codegraph-tab", dataset: { name: "meta-codegraph-tab" } }, [opbar, view]);

    var navBtn = el("button", {
      className: "meta-codegraph-btn active",
      dataset: { name: "meta-codegraph-btn" },
      onclick: function () { showPage("meta-codegraph-tab"); },
    }, "代码图");
    var sidebar = el("div", { className: "meta-sidebar", dataset: { name: "meta-sidebar" } }, [
      el("div", { className: "meta-sidebar-title", dataset: { name: "meta-sidebar-title" } }, "本体"),
      navBtn,
    ]);

    detailEl = el("div", { className: "meta-codegraph-detail", dataset: { name: "meta-codegraph-detail" } });

    var viewport = el("div", { className: "meta-viewport", dataset: { name: "meta-viewport" } }, [tab]);
    var panel = el("div", { className: "meta-panel", dataset: { name: "meta-panel" } }, [
      detailEl,
      el("button", { className: "close-meta-btn", dataset: { name: "close-meta-btn" }, onclick: closeMeta }, "关闭"),
    ]);

    var win = el("div", { className: "meta-window", dataset: { name: "meta-window" } }, [sidebar, viewport, panel]);
    overlay = el("div", { className: "meta-modal", dataset: { name: "meta-modal" } }, [win]);
    overlay.addEventListener("click", function (e) { if (e.target === overlay) closeMeta(); });
    document.body.appendChild(overlay);
    clearSelection();
  }

  // Page switcher inside meta-viewport. Only one page exists today; the
  // sidebar button stays active and future pages plug in here.
  function showPage(name) {
    overlay.querySelectorAll(".meta-viewport > [data-name]").forEach(function (node) {
      node.hidden = node.getAttribute("data-name") !== name;
    });
    overlay.querySelectorAll(".meta-sidebar [data-name]").forEach(function (node) {
      node.classList.toggle("active", node.getAttribute("data-name") === "meta-codegraph-btn");
    });
  }

  // ---- Open / close ----
  function openMeta() {
    if (!overlay) buildShell();
    overlay.style.display = "flex";
    loadGraph(false);
    // The canvas is measured only after the modal is laid out.
    requestAnimationFrame(function () {
      if (cy) { cy.resize(); fitGraph(); }
    });
  }

  function closeMeta() {
    if (overlay) overlay.style.display = "none";
  }

  // ---- Data ----
  function loadGraph(force) {
    if (!overlay) return;
    if (data && !force) {
      if (cy) { cy.resize(); fitGraph(); }
      return;
    }
    setStatus("加载依赖数据…", "loading");
    fetch(DATA_URL)
      .then(function (res) {
        if (!res.ok) throw new Error("HTTP " + res.status);
        return res.json();
      })
      .then(function (json) {
        data = json;
        render(json);
        renderArch(json.arch);
        setStatus(
          "文件 " + json.nodes.length + " · 边 " + json.edges.length +
            " · 生成于 " + new Date(json.generatedAt).toLocaleString(),
          "ready"
        );
      })
      .catch(function (e) {
        setStatus(
          "加载失败：" + (e && e.message ? e.message : e) +
            "（先运行 node scripts/graph/scan.js 生成 graph-data.json）",
          "error"
        );
      });
  }

  function setStatus(text, state) {
    if (!statusEl) return;
    statusEl.textContent = text;
    statusEl.setAttribute("data-state", state || "");
  }

  function elementsOf(json) {
    var nodes = json.nodes.map(function (n) {
      return {
        data: {
          id: n.id,
          label: labelOf(n.id),
          layer: n.layer,
          subdir: n.subdir,
          lines: n.lines,
          color: LAYER_COLORS[n.layer] || LAYER_COLORS.other,
        },
      };
    });
    var edges = json.edges.map(function (e, i) {
      return {
        data: { id: "e" + i, source: e.from, target: e.to, kind: e.kind, rule: e.rule || "" },
        classes: e.kind === "dynamic" ? "dynamic" : "static",
      };
    });
    return nodes.concat(edges);
  }

  function labelOf(id) {
    var parts = id.split("/");
    return parts.length > 1 ? parts.slice(-2).join("/") : id;
  }

  function render(json) {
    if (cy) {
      cy.destroy();
      cy = null;
    }
    canvasEl.innerHTML = "";
    if (!window.cytoscape || !window.cytoscapeDagre) {
      setStatus("缺少 UI 依赖：请确认 ui/web/vendor/cytoscape.min.js 与 cytoscape-dagre.js 存在", "error");
      return;
    }
    var style = [
      {
        selector: "node",
        style: {
          "background-color": "data(color)",
          label: "data(label)",
          color: "#1f2937",
          "font-size": 10,
          "text-valign": "center",
          "text-halign": "center",
          "text-wrap": "ellipsis",
          "text-max-width": "86px",
          width: "label",
          height: 20,
          padding: "4px 6px",
          shape: "round-rectangle",
          "border-width": 1,
          "border-color": "#ffffff",
          "background-opacity": 0.92,
          "text-rotation": "none",
        },
      },
      {
        selector: "edge",
        style: {
          width: 1,
          "line-color": "#cbd5e1",
          "target-arrow-color": "#cbd5e1",
          "target-arrow-shape": "triangle",
          "arrow-scale": 0.6,
          "curve-style": "bezier",
          "control-point-step-size": 20,
          opacity: 0.7,
        },
      },
      { selector: "edge.dynamic", style: { "line-style": "dashed", width: 1.2 } },
      { selector: ".incoming", style: { "line-color": INCOMING, "target-arrow-color": INCOMING, width: 2, opacity: 1 } },
      { selector: ".outgoing", style: { "line-color": OUTGOING, "target-arrow-color": OUTGOING, width: 2, opacity: 1 } },
      { selector: ".selected", style: { "border-width": 2, "border-color": "#111827" } },
      { selector: ".neighbor-in", style: { "border-width": 2, "border-color": INCOMING } },
      { selector: ".neighbor-out", style: { "border-width": 2, "border-color": OUTGOING } },
      { selector: ".faded", style: { opacity: 0.18 } },
    ];
    try {
      cy = window.cytoscape({
        container: canvasEl,
        elements: elementsOf(json),
        style: style,
        // Left-to-right keeps deep chains readable and brings the wide
        // tool/fan-out layer under control.
        layout: {
          name: "dagre",
          rankDir: "LR",
          nodeSep: 10,
          rankSep: 40,
          edgeSep: 4,
          animate: false,
          stop: function () {
            // Fit once dagre has placed every node; the layout runs before the
            // canvas has its final size, so fitting inside the layout call is
            // unreliable.
            fitGraph();
          },
        },
        wheelSensitivity: 0.2,
        minZoom: 0.08,
        maxZoom: 3,
      });
    } catch (e) {
      setStatus("渲染失败：" + (e && e.message ? e.message : e), "error");
      return;
    }
    applyZoomLabelMode();
    cy.on("zoom", applyZoomLabelMode);
    cy.on("tap", "node", function (evt) { selectNode(evt.target.id()); });
    cy.on("tap", "edge", function (evt) { showEdgeDetail(evt.target.data()); });
    cy.on("tap", function (evt) { if (evt.target === cy) clearSelection(); });
    if (selectedId && cy.getElementById(selectedId).length) applySelection(selectedId);
    else clearSelection();
  }

  // ---- Architecture rules ----
  function renderArch(arch) {
    if (!archBadge || !archPanelEl) return;
    if (!arch) {
      archBadge.textContent = "架构规则 —";
      archBadge.setAttribute("data-state", "unknown");
      return;
    }
    var s = arch.summary;
    archBadge.textContent = s.error
      ? "架构规则 " + s.error + " 违规"
      : s.warn
        ? "架构规则 " + s.warn + " 警告"
        : "架构规则 通过";
    archBadge.setAttribute("data-state", s.error ? "error" : s.warn ? "warn" : "ok");
    archPanelEl.innerHTML = archPanelHtml(arch);
    Array.prototype.forEach.call(archPanelEl.querySelectorAll("[data-focus]"), function (node) {
      node.addEventListener("click", function () {
        var id = node.getAttribute("data-focus");
        if (cy && cy.getElementById(id).length) selectNode(id);
      });
    });
  }

  function archPanelHtml(arch) {
    var out = ['<div class="meta-arch-head">架构规则检查（' + arch.summary.rules + " 条规则）</div>"];
    if (!arch.violations.length && !arch.cycles.length) {
      out.push('<div class="meta-arch-ok">全部通过，代码符合分层设计。</div>');
      return out.join("");
    }
    var groups = {};
    arch.violations.forEach(function (v) {
      (groups[v.rule] = groups[v.rule] || { severity: v.severity, description: v.description, items: [] }).items.push(v);
    });
    Object.keys(groups).forEach(function (ruleId) {
      var g = groups[ruleId];
      out.push('<div class="meta-arch-group" data-severity="' + g.severity + '">');
      out.push('<div class="meta-arch-rule">' + esc(ruleId) + " <span class=\"meta-arch-count\">" + g.items.length + "</span></div>");
      out.push('<div class="meta-arch-desc">' + esc(g.description) + "</div>");
      g.items.forEach(function (v) {
        out.push(
          '<div class="meta-arch-item">' +
            '<button class="meta-arch-file" data-focus="' + esc(v.from) + '">' + esc(v.from) + "</button>" +
            '<span class="meta-arch-arrow">→</span>' +
            '<button class="meta-arch-file" data-focus="' + esc(v.to) + '">' + esc(v.to) + "</button>" +
            '<span class="meta-arch-tag">' + esc(v.reason) + "</span>" +
            (v.candidate ? '<span class="meta-arch-tag candidate">候选公共设施</span>' : "") +
          "</div>"
        );
      });
      out.push("</div>");
    });
    arch.cycles.forEach(function (c) {
      out.push('<div class="meta-arch-group" data-severity="' + c.severity + '">');
      out.push('<div class="meta-arch-rule">' + esc(c.rule) + "</div>");
      out.push('<div class="meta-arch-desc">' + esc(c.description) + "</div>");
      out.push('<div class="meta-arch-item">' + c.members.map(function (m) {
        return '<button class="meta-arch-file" data-focus="' + esc(m) + '">' + esc(m) + "</button>";
      }).join('<span class="meta-arch-arrow">↔</span>') + "</div>");
      out.push("</div>");
    });
    return out.join("");
  }

  function toggleArchPanel() {
    if (!archPanelEl) return;
    archPanelEl.hidden = !archPanelEl.hidden;
  }

  // Below the readable threshold, node labels turn into ellipsis so the
  // overview reads as a structure map instead of a smear of text.
  function applyZoomLabelMode() {
    if (!cy) return;
    var show = cy.zoom() >= LABEL_ZOOM;
    cy.style()
      .selector("node")
      .style("label", show ? "data(label)" : "…")
      .update();
  }

  function fitGraph() {
    if (!cy || !canvasEl) return;
    if (!canvasEl.clientWidth) return;
    cy.resize();
    cy.fit(null, 30);
  }

  function selectNode(id) {
    if (!cy) return;
    selectedId = id;
    applySelection(id);
    focusOn(id);
  }

  // Centre the selected node at a zoom level where labels are readable.
  // The overview stays one click away via the fit button.
  function focusOn(id) {
    var node = cy.getElementById(id);
    if (!node.length) return;
    cy.animate({ center: { eles: node }, zoom: Math.max(cy.zoom(), FOCUS_ZOOM), duration: 250 });
  }

  function applySelection(id) {
    var node = cy.getElementById(id);
    if (!node.length) return;
    var incoming = node.incomers("node");
    var outgoing = node.outgoers("node");
    var edges = node.connectedEdges();

    cy.elements().removeClass("selected incoming outgoing neighbor-in neighbor-out faded");
    cy.elements().not(edges).not(edges.connectedNodes()).not(node).addClass("faded");
    edges.forEach(function (edge) {
      edge.addClass(edge.data("target") === id ? "incoming" : "outgoing");
    });
    node.addClass("selected");
    incoming.addClass("neighbor-in");
    outgoing.addClass("neighbor-out");

    showNodeDetail(node.data(), incoming, outgoing);
  }

  function clearSelection() {
    selectedId = null;
    if (cy) cy.elements().removeClass("selected incoming outgoing neighbor-in neighbor-out faded");
    if (detailEl) {
      detailEl.innerHTML = '<div class="meta-detail-hint">点击文件节点查看两类边：谁依赖它（入边）、它依赖谁（出边）；虚线边来自运行时规则表。</div>';
    }
  }

  function showNodeDetail(nodeData, incoming, outgoing) {
    if (!detailEl) return;
    var html = [];
    html.push('<div class="meta-detail-title">' + esc(nodeData.id) + "</div>");
    html.push('<div class="meta-detail-meta">层级 ' + esc(nodeData.layer) + " · " + esc(String(nodeData.lines)) + " 行</div>");
    html.push('<div class="meta-detail-group"><span class="meta-dot dot-in"></span>被依赖 ' + incoming.length + "（入边）</div>");
    html.push(sideList(incoming));
    html.push('<div class="meta-detail-group"><span class="meta-dot dot-out"></span>依赖 ' + outgoing.length + "（出边）</div>");
    html.push(sideList(outgoing));
    detailEl.innerHTML = html.join("");
    Array.prototype.forEach.call(detailEl.querySelectorAll("[data-focus]"), function (node) {
      node.addEventListener("click", function () { selectNode(node.getAttribute("data-focus")); });
    });
  }

  function showEdgeDetail(edgeData) {
    if (!detailEl) return;
    var kind = edgeData.kind === "dynamic" ? "dynamic（运行时规则）" : edgeData.kind === "import" ? "import" : "require";
    detailEl.innerHTML =
      '<div class="meta-detail-title">' + esc(edgeData.source) + "</div>" +
      '<div class="meta-detail-meta">→ ' + esc(edgeData.target) + "</div>" +
      '<div class="meta-detail-meta">类型 ' + esc(kind) + "</div>" +
      (edgeData.rule ? '<div class="meta-detail-meta">规则 ' + esc(edgeData.rule) + "</div>" : "");
  }

  function sideList(nodes) {
    if (!nodes.length) return '<div class="meta-side-empty">—</div>';
    return '<div class="meta-side-list">' + nodes.map(function (n) {
      return '<button class="meta-side-item" data-focus="' + esc(n.id()) + '">' + esc(n.data("label")) + "</button>";
    }).join("") + "</div>";
  }

  function onSearch() {
    if (!cy) return;
    var q = (searchEl.value || "").trim().toLowerCase();
    cy.elements().removeClass("faded");
    if (!q) return;
    cy.nodes().forEach(function (n) {
      if (n.id().toLowerCase().indexOf(q) < 0) n.addClass("faded");
    });
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  // ---- Public surface ----
  App.initGraph = function initGraph() {
    var btn = document.getElementById("metaBtn");
    if (btn) btn.addEventListener("click", openMeta);
  };

  // Read-only inspection surface for debugging the panel.
  App.meta = {
    open: openMeta,
    close: closeMeta,
    instance: function () { return cy; },
    data: function () { return data; },
    select: selectNode,
    clear: clearSelection,
  };
})();
